// Sélectionne un produit dans la rotation : le workflow tourne tous les 2 jours,
// on change donc de produit à chaque exécution (jour de l'année divisé par 2)
const produits = [
  { nom: "Gel Nettoyant Purifiant Botanique", categorie: "Nettoyant visage", typePeau: "Toutes peaux, y compris sensibles et réactives", ingredientsCles: "Aloe vera bio, extrait de menthe douce, glycérine végétale", usage: "Matin et soir, étape 1 du rituel. Sur peau humide, masser puis rincer à l'eau tiède", benefices: "Élimine les impuretés sans dessécher et préserve le film hydrolipidique de la peau", precautions: "Aucune connue, sans sulfates ni savon", prix: "24€ (150ml)", particularite: "Nouveauté de la collection, adaptée à un usage biquotidien" },
  { nom: "Brume Tonique Active à la Rose", categorie: "Tonique visage en brume", typePeau: "Toutes peaux, en particulier sèches et sensibles", ingredientsCles: "Hydrolat de rose de Damas, eau florale de camomille", usage: "Matin et soir, étape 2 du rituel, après le nettoyage. Vaporiser à 20 cm du visage. Aussi dans la journée pour rafraîchir la peau", benefices: "Rééquilibre la peau après le nettoyage, apaise, rafraîchit et prépare aux soins suivants", precautions: "Aucune connue, sans alcool", prix: "28€ (100ml)" },
  { nom: "Élixir Éclat Vitamine C", categorie: "Sérum visage", typePeau: "Toutes peaux, en particulier ternes ou fatiguées, y compris mixtes", ingredientsCles: "Vitamine C d'origine végétale, extrait de thé vert bio", usage: "Le matin, étape 3 du rituel. 3 à 4 gouttes sur peau propre, avant la crème", benefices: "Ravive l'éclat du teint. Antioxydant, il aide à protéger la peau des agressions extérieures comme la pollution", precautions: "Peaux très réactives : commencer un jour sur deux. Ne pas appliquer sur une peau irritée", prix: "42€ (30ml)", particularite: "Soin favori de la communauté Luméa" },
  { nom: "Crème Hydratante Intense", categorie: "Crème visage", typePeau: "Peaux normales à sèches, y compris sensibles", ingredientsCles: "Acide hyaluronique végétal, huile de jojoba bio", usage: "Le soir, étape 3 du rituel, en dernière étape sur peau propre. Aussi le matin pour les peaux très sèches", benefices: "Hydrate en profondeur, nourrit et aide à protéger la barrière cutanée. La peau reste souple et confortable", precautions: "Aucune connue, sans parfum de synthèse", prix: "38€ (50ml)" }
];

const jourAnnee = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0)) / 86400000);
const produit = produits[Math.floor(jourAnnee / 2) % produits.length];

return [{ json: produit }];

